document.getElementById("uploadModeSelect").addEventListener("change",function(){var e=document.getElementById("imageKitKeyContainer");"imagekit"===this.value?(e.classList.remove("d-none"),e.classList.add("d-block")):(e.classList.remove("d-block"),e.classList.add("d-none"))});document.getElementById("geminiSwitch").addEventListener("change",function(){var e=document.getElementById("geminiAiContainer"),t=document.getElementById("enable_gemini");this.checked?(e.classList.remove("d-none"),e.classList.add("d-flex"),t.value="yes"):(e.classList.remove("d-flex"),e.classList.add("d-none"),t.value="no")});
